const os=require('node:os'),privateFiles={"server_reallocations/create_reallocations.js":"function create_reallocations(resources) {\n    const { all, audit, get, run, tx, badRequest, conflict, forbidden, notFound, newId, nowIso, effectiveSet, launchSet, assertTargetsFit, contentOf, goalObj, goalRow, visibleGoal, writeGoalVersion, canReadGoal, memberName, nameTo, assertRevisionReached, optStr, revisionRead, COUNTER_SAME_AS_PROPOSAL } = resources;\n    // Reallocations (PORT29, main #29): a proposal to change the target share of agent time of one or more goals at once,\n    // so time can move from one goal to another without passing 100% in between. It follows the change request model\n    // (lib/v2/changes.ts) rather than #29's \"every owner approves, then it applies\":\n    //   - each goal whose target changes needs one approval from its effective approval set (owner, team leads and, for a\n    //     company goal, workspace owners, after the requester rule, lib/v2/approval.ts). The requester's own goals are\n    //     approved by asking; a counter's author approves the goals they may approve for by writing it.\n    //   - once every goal is approved the proposal is approved and its launch is pending: no goal version, no directive.\n    //   - launch (someone in every goal's launch set who can read every goal) writes each goal's next version with its\n    //     new target through writeGoalVersion, authored by the person who approved that goal, so bound sessions get the\n    //     usual goal_version directive. not_yet records that it waits; approve_and_launch does both.\n    //   - any newer version of one of its goals (an owner's edit, a launch, the goal achieved or dropped) supersedes an\n    //     open or approved-unlaunched proposal: the goal outran it, nothing reaches agents, and the requester proposes\n    //     again (supersedeReallocations, called by writeGoalVersion).\n    // Everyone who can read one of its goals can read a proposal (as with change requests); a goal they can't read is\n    // unnamed and shows no numbers or approvers. Viewers can't act.\n    //   pending -> approved | countered | rejected | withdrawn | superseded;  countered -> pending (accept_counter)\n    const REALLOCATION_STATES = [\"pending\", \"countered\", \"approved\", \"rejected\", \"withdrawn\", \"superseded\"];\n    const REALLOCATION_ACTIONS = [\"approve\", \"approve_and_launch\", \"launch\", \"not_yet\", \"counter\", \"accept_counter\", \"reject\", \"withdraw\"];\n    /** Goals one proposal may name. */\n    const REALLOCATION_GOALS_MAX = 50;\n    const NOTE_MAX = 1000;\n    const rowOf = (ws, id) => get(\"SELECT * FROM v2_reallocations WHERE ws_id = ? AND id = ?\", ws, id);\n    const revisionOf = (id, revision) => get(\"SELECT * FROM v2_reallocation_revisions WHERE reallocation_id = ? AND revision = ?\", id, revision);\n    const targetsOf = (id, revision) => JSON.parse(revisionOf(id, revision).targets_json);\n    /** goal id -> who approved it, at this revision. */\n    const approvalsOf = (id, revision) => new Map(all(\"SELECT goal_id, user_id FROM v2_reallocation_approvals WHERE reallocation_id = ? AND revision = ?\", id, revision).map((a) => [a.goal_id, a.user_id]));\n    /** The targets of a body, [{goal_id, target_share}]: each a goal the caller can read (404) that is active (409), with a\n     *  whole percent from 0 to 100 or null (400), at most once. Keeps the goals whose target changes; none is 409. */\n    function targetsIn(pp, v) {\n        if (!Array.isArray(v) || !v.length)\n            throw badRequest(\"targets must list at least one { goal_id, target_share }\");\n        if (v.length > REALLOCATION_GOALS_MAX)\n            throw badRequest(`targets: at most ${REALLOCATION_GOALS_MAX}`);\n        const out = [];\n        const seen = new Set();\n        for (const raw of v) {\n            if (!raw || typeof raw !== \"object\" || Array.isArray(raw))\n                throw badRequest(\"each target must be { goal_id, target_share }\");\n            const t = raw;\n            const share = t.target_share;\n            if (share !== null && (typeof share !== \"number\" || !Number.isInteger(share) || share < 0 || share > 100))\n                throw badRequest(\"target_share must be a whole percent from 0 to 100, or null\");\n            const g = visibleGoal(pp, typeof t.goal_id === \"string\" ? t.goal_id : \"\");\n            if (seen.has(g.id))\n                throw badRequest(\"Each goal can appear once\");\n            seen.add(g.id);\n            if (g.status !== \"active\")\n                throw conflict(\"goal_not_active\", \"A goal in this proposal is achieved or dropped, so its target can't change.\");\n            if ((g.target_share ?? null) !== share)\n                out.push({ goal_id: g.id, base_version: g.version, from_share: g.target_share ?? null, target_share: share });\n        }\n        if (!out.length)\n            throw conflict(\"no_change\", \"These targets are already set, so there is nothing to propose.\");\n        return out;\n    }\n    /** Whether two revisions ask for the same targets: the same goals, each with the same target share. */\n    function sameTargets(a, b) {\n        const of = new Map(b.map((t) => [t.goal_id, t.target_share]));\n        return a.length === b.length && a.every((t) => of.has(t.goal_id) && of.get(t.goal_id) === t.target_share);\n    }\n    const fits = (ws, targets) => assertTargetsFit(ws, new Map(targets.map((t) => [t.goal_id, t.target_share])));\n    /** Record `user`'s approval for every goal of this revision they may approve for and nobody approved yet. Returns how\n     *  many goals that approved. */\n    function approveAs(r, revision, user, at) {\n        const done = approvalsOf(r.id, revision);\n        let n = 0;\n        for (const t of targetsOf(r.id, revision)) {\n            const g = goalRow(r.ws_id, t.goal_id);\n            if (!g || done.has(t.goal_id) || !effectiveSet(g, r.requester_id).includes(user))\n                continue;\n            n += run(\"INSERT OR IGNORE INTO v2_reallocation_approvals (ws_id, reallocation_id, revision, goal_id, user_id, at) VALUES (?, ?, ?, ?, ?, ?)\", r.ws_id, r.id, revision, t.goal_id, user, at);\n        }\n        return n;\n    }\n    /** When every goal of the current revision is approved: approved, launch pending. Inside the caller's tx. */\n    function settle(r, at) {\n        const done = approvalsOf(r.id, r.revision);\n        if (!targetsOf(r.id, r.revision).every((t) => done.has(t.goal_id)))\n            return false;\n        run(\"UPDATE v2_reallocations SET state = 'approved', launch = 'pending', decided_at = ?, updated_at = ? WHERE id = ?\", at, at, r.id);\n        audit(r.ws_id, null, \"reallocation.approved\", r.id, at);\n        return true;\n    }\n    function writeRevision(r, revision, targets, note, author, at) {\n        run(\"INSERT INTO v2_reallocation_revisions (ws_id, reallocation_id, revision, targets_json, note, author_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)\", r.ws_id, r.id, revision, JSON.stringify(targets), note, author, at);\n    }\n    /** Ids of every goal any revision names. */\n    const goalsOf = (id) => [...new Set(all(\"SELECT targets_json FROM v2_reallocation_revisions WHERE reallocation_id = ?\", id).flatMap((v) => JSON.parse(v.targets_json).map((t) => t.goal_id)))];\n    const readable = (pp, ws, goalId) => {\n        const g = goalRow(ws, goalId);\n        return !!g && canReadGoal(pp, goalObj(g));\n    };\n    /** The proposal if the caller can read one of its goals, else 404. */\n    function visible(pp, id) {\n        const r = rowOf(pp.wsId, id);\n        if (!r || !goalsOf(r.id).some((g) => readable(pp, r.ws_id, g)))\n            throw notFound();\n        return r;\n    }\n    /** POST …/reallocations { targets: [{goal_id, target_share}], note? } -> 201 (owners and members). */\n    async function createReallocation(pp, b) {\n        if (pp.wsRole === \"viewer\")\n            throw forbidden(\"read_only\", \"Viewers can look but not change anything.\");\n        const targets = targetsIn(pp, b.targets);\n        const note = optStr(b, \"note\", NOTE_MAX);\n        fits(pp.wsId, targets);\n        const id = newId(\"rl\");\n        const at = nowIso();\n        await tx(() => {\n            for (const t of targets)\n                if (goalRow(pp.wsId, t.goal_id).version !== t.base_version)\n                    throw conflict(\"stale_version\", \"A goal changed while this was being sent. Reload the page and propose again.\");\n            run(\"INSERT INTO v2_reallocations (id, ws_id, requester_id, state, revision, created_at, updated_at) VALUES (?, ?, ?, 'pending', 1, ?, ?)\", id, pp.wsId, pp.userId, at, at);\n            writeRevision({ id, ws_id: pp.wsId }, 1, targets, note, pp.userId, at);\n            audit(pp.wsId, pp.userId, \"reallocation.requested\", id, at);\n            approveAs({ id, ws_id: pp.wsId, requester_id: pp.userId }, 1, pp.userId, at); // the requester's own goals\n            settle(rowOf(pp.wsId, id), at);\n        });\n        return view(pp, rowOf(pp.wsId, id));\n    }\n    /** May `user` launch it: in every goal's launch set, and able to read every goal. */\n    function mayLaunch(pp, r) {\n        return targetsOf(r.id, r.revision).every((t) => {\n            const g = goalRow(r.ws_id, t.goal_id);\n            return !!g && launchSet(g, r.requester_id).includes(pp.userId) && canReadGoal(pp, goalObj(g));\n        });\n    }\n    /** Write each goal's next version with its new target (decreases first, so the workspace's targets never pass 100 on\n     *  the way), authored by whoever approved that goal. Inside the caller's tx, after the proposal is marked launched. */\n    function launchTargets(r, actor, at) {\n        const approvedBy = approvalsOf(r.id, r.revision);\n        const targets = targetsOf(r.id, r.revision)\n            .map((t) => ({ t, g: goalRow(r.ws_id, t.goal_id) }))\n            .sort((a, b) => (a.t.target_share ?? 0) - (a.g?.target_share ?? 0) - ((b.t.target_share ?? 0) - (b.g?.target_share ?? 0)));\n        for (const { t, g } of targets) {\n            // writeGoalVersion supersedes a proposal whose goal moved, so this is a guard, not a path.\n            if (!g || g.status !== \"active\" || g.version !== t.base_version)\n                throw conflict(\"stale_version\", \"A goal in this proposal changed, so it can't be launched.\");\n            writeGoalVersion(g, { ...contentOf(g), target_share: t.target_share }, actor, at, approvedBy.get(t.goal_id) ?? actor);\n        }\n    }\n    /** Why an action on a target change in another state is refused (409 wrong_state), in the app's words (\"declined\", never\n     *  \"rejected\") and naming who did it, as change requests and alignments say it (C8-1's sweep); the reader is \"you\"\n     *  (c9 W3: \"You declined this proposal, …\", never the owner's own name). */\n    function stateRefusal(r, reader) {\n        switch (r.state) {\n            case \"pending\":\n                return \"This proposal is waiting for approval.\";\n            case \"countered\": {\n                const author = revisionOf(r.id, r.revision).author_id;\n                if (author === reader)\n                    return `You countered this proposal; it waits on ${nameTo(r.requester_id, reader)} to accept it.`;\n                return `This proposal was countered by ${memberName(author)}; review the counter.`;\n            }\n            case \"approved\":\n                return \"This proposal is already approved.\";\n            case \"rejected\":\n                if (r.decided_by === reader)\n                    return \"You declined this proposal, so nothing changes.\";\n                return `This proposal was declined${r.decided_by ? ` by ${memberName(r.decided_by)}` : \"\"}, so nothing changes.`;\n            case \"withdrawn\":\n                if (r.requester_id === reader)\n                    return \"You withdrew this proposal, so nothing changes.\";\n                return `This proposal was withdrawn by ${memberName(r.requester_id)}, so nothing changes.`;\n            case \"superseded\":\n                return \"This proposal was superseded: one of its goals got a newer version or was closed first, so nothing changes.\";\n        }\n    }\n    async function actOnReallocation(pp, id, action, b) {\n        visible(pp, id);\n        if (pp.wsRole === \"viewer\")\n            throw forbidden(\"read_only\", \"Viewers can look but not change anything.\");\n        const me = pp.userId;\n        const at = nowIso();\n        // A revision, when sent, is a whole number (400 in words otherwise, c11 W1) that the proposal has reached: one it\n        // never reached was never read, so it is 400, not a stale refusal (c11 W3). Both are checked before the rest of the\n        // body, as on alignments and change requests (E2E-WEB cycle 12 C12-2).\n        const sent = revisionRead(b, true);\n        await tx(() => {\n            const r = rowOf(pp.wsId, id); // read inside the transaction\n            assertRevisionReached(\"proposal\", sent, r.revision);\n            // A counter's targets: reading checks each goal's visibility and can throw 404.\n            const countered = action === \"counter\" ? targetsIn(pp, b.targets) : null;\n            const note = action === \"counter\" || action === \"reject\" ? optStr(b, action === \"reject\" ? \"reason\" : \"note\", NOTE_MAX) : null;\n            const targets = targetsOf(r.id, r.revision);\n            const isRequester = r.requester_id === me;\n            const isApprover = targets.some((t) => {\n                const g = goalRow(r.ws_id, t.goal_id);\n                return !!g && effectiveSet(g, r.requester_id).includes(me);\n            });\n            const inState = (...s) => {\n                if (!s.includes(r.state))\n                    throw conflict(\"wrong_state\", stateRefusal(r, me));\n            };\n            // A counter meanwhile names its author (\"you\" to the reader), as a change request's stale refusal does (c10 C10-2).\n            const expectRevision = (required) => {\n                if (!((required || b.revision !== undefined) && b.revision !== r.revision))\n                    return;\n                const author = r.state === \"countered\" ? revisionOf(r.id, r.revision).author_id : null;\n                const what = author ? `${nameTo(author, me)} countered it, and it is now at revision ${r.revision}` : `it is now at revision ${r.revision}`;\n                throw conflict(\"stale_revision\", `This proposal changed after you read it: ${what}. Read it again and decide again.`);\n            };\n            const approverOnly = () => {\n                if (!isApprover)\n                    throw forbidden(\"not_an_approver\", \"Only someone who can approve for one of these goals can do this.\");\n            };\n            const requesterOnly = () => {\n                if (!isRequester)\n                    throw forbidden(\"not_requester\", \"Only the person who asked can do this.\");\n            };\n            const launcherOnly = () => {\n                if (!mayLaunch(pp, r))\n                    throw forbidden(\"not_a_launcher\", \"Only someone who can launch for every goal in it (an approver of each, or a workspace owner who can read them all) can launch it.\");\n            };\n            const launchable = () => {\n                if (r.state !== \"approved\" || (r.launch !== \"pending\" && r.launch !== \"not_yet\"))\n                    throw conflict(\"wrong_state\", r.launch === \"launched\" ? `These targets were already launched by ${r.launch_by ? nameTo(r.launch_by, me) : \"someone\"}.` : stateRefusal(r, me));\n            };\n            const approve = () => {\n                approverOnly();\n                inState(\"pending\");\n                expectRevision(true);\n                if (!approveAs(r, r.revision, me, at))\n                    throw conflict(\"already_approved\", \"The goals you can approve for are already approved.\");\n                run(\"UPDATE v2_reallocations SET updated_at = ? WHERE id = ?\", at, r.id);\n                audit(r.ws_id, me, \"reallocation.approval\", r.id, at);\n                return settle(r, at);\n            };\n            const launch = () => {\n                launcherOnly();\n                fits(r.ws_id, targetsOf(r.id, r.revision));\n                // Launched first, so the new versions' supersede step leaves this proposal alone.\n                run(\"UPDATE v2_reallocations SET launch = 'launched', launch_by = ?, launch_at = ?, updated_at = ? WHERE id = ?\", me, at, at, r.id);\n                launchTargets(r, me, at);\n                audit(r.ws_id, me, \"reallocation.launched\", r.id, at);\n            };\n            switch (action) {\n                case \"approve\":\n                    approve();\n                    break;\n                case \"approve_and_launch\":\n                    launcherOnly(); // before approving: nothing is written unless both can happen\n                    if (!approve())\n                        throw conflict(\"not_ready\", \"Other goals in this proposal still need an approval, so it can't launch yet; approve it instead.\");\n                    launch();\n                    break;\n                case \"launch\":\n                    launchable();\n                    expectRevision(false);\n                    launch();\n                    break;\n                case \"not_yet\":\n                    launcherOnly();\n                    launchable();\n                    expectRevision(false);\n                    // Already not yet (in another tab, or by another launcher): recording it again would change nothing (c11 W2).\n                    if (r.launch === \"not_yet\") {\n                        const who = r.launch_by === me ? \"You\" : r.launch_by ? memberName(r.launch_by) : \"Someone\";\n                        throw conflict(\"wrong_state\", `${who} already decided not yet, so nothing changes: agents keep the old targets until someone launches the new ones.`);\n                    }\n                    run(\"UPDATE v2_reallocations SET launch = 'not_yet', launch_by = ?, launch_at = ?, updated_at = ? WHERE id = ?\", me, at, at, r.id);\n                    audit(r.ws_id, me, \"reallocation.not_yet\", r.id, at);\n                    break;\n                case \"counter\": {\n                    approverOnly();\n                    if (isRequester)\n                        throw forbidden(\"not_an_approver\", \"Withdraw and propose again to change your own proposal.\");\n                    inState(\"pending\");\n                    expectRevision(false);\n                    // A counter that asks for exactly the proposal's targets suggests nothing: approving it is, as a change\n                    // request's counter says (E2E-WEB cycle 13 W5).\n                    if (sameTargets(countered, targets))\n                        throw conflict(\"no_change\", COUNTER_SAME_AS_PROPOSAL);\n                    fits(r.ws_id, countered);\n                    const next = r.revision + 1;\n                    writeRevision(r, next, countered, note, me, at);\n                    run(\"UPDATE v2_reallocations SET state = 'countered', revision = ?, updated_at = ? WHERE id = ?\", next, at, r.id);\n                    approveAs(r, next, me, at); // the counter's author agrees with it\n                    audit(r.ws_id, me, \"reallocation.countered\", r.id, at);\n                    break;\n                }\n                case \"accept_counter\":\n                    requesterOnly();\n                    inState(\"countered\");\n                    expectRevision(false);\n                    for (const t of targets)\n                        if (goalRow(r.ws_id, t.goal_id)?.version !== t.base_version)\n                            throw conflict(\"stale_version\", \"A goal in this proposal changed after the counter, so it can't go back for approval. Withdraw it and propose again.\");\n                    fits(r.ws_id, targets);\n                    run(\"UPDATE v2_reallocations SET state = 'pending', updated_at = ? WHERE id = ?\", at, r.id);\n                    approveAs(r, r.revision, me, at);\n                    audit(r.ws_id, me, \"reallocation.counter_accepted\", r.id, at);\n                    settle({ ...r, state: \"pending\" }, at);\n                    break;\n                case \"reject\":\n                    approverOnly();\n                    if (isRequester)\n                        throw forbidden(\"not_an_approver\", \"Withdraw your own proposal instead.\");\n                    inState(\"pending\", \"countered\");\n                    expectRevision(false);\n                    run(\"UPDATE v2_reallocations SET state = 'rejected', decided_by = ?, decision_note = ?, decided_at = ?, updated_at = ? WHERE id = ?\", me, note, at, at, r.id);\n                    audit(r.ws_id, me, \"reallocation.rejected\", r.id, at);\n                    break;\n                case \"withdraw\":\n                    requesterOnly();\n                    inState(\"pending\", \"countered\");\n                    expectRevision(false);\n                    run(\"UPDATE v2_reallocations SET state = 'withdrawn', decided_at = ?, updated_at = ? WHERE id = ?\", at, at, r.id);\n                    audit(r.ws_id, me, \"reallocation.withdrawn\", r.id, at);\n                    break;\n            }\n        });\n        return view(pp, rowOf(pp.wsId, id));\n    }\n    /** Inside writeGoalVersion's tx: every open (pending or countered) or approved-unlaunched proposal whose current\n     *  revision names this goal is superseded, audited with the person whose action wrote the version. */\n    function supersedeReallocations(ws, goalId, actorId, at) {\n        const rows = all(`SELECT r.id FROM v2_reallocations r JOIN v2_reallocation_revisions v ON v.reallocation_id = r.id AND v.revision = r.revision\n     WHERE r.ws_id = ? AND (r.state IN ('pending','countered') OR (r.state = 'approved' AND r.launch IN ('pending','not_yet')))\n     AND EXISTS (SELECT 1 FROM json_each(v.targets_json) j WHERE json_extract(j.value, '$.goal_id') = ?)`, ws, goalId);\n        for (const r of rows) {\n            run(\"UPDATE v2_reallocations SET launch = CASE WHEN state = 'approved' THEN 'superseded' ELSE launch END, state = 'superseded', decided_at = COALESCE(decided_at, ?), updated_at = ? WHERE id = ?\", at, at, r.id);\n            audit(ws, actorId, \"reallocation.superseded\", r.id, at);\n        }\n    }\n    // ---- reading ----\n    function view(pp, r) {\n        const person = (id) => (id ? { id, name: memberName(id) } : null);\n        const approved = approvalsOf(r.id, r.revision);\n        const me = pp.userId;\n        let isApprover = false;\n        let canApproveNow = false;\n        const targets = targetsOf(r.id, r.revision).map((t) => {\n            const g = goalRow(r.ws_id, t.goal_id);\n            const seen = !!g && canReadGoal(pp, goalObj(g));\n            const set = g ? effectiveSet(g, r.requester_id) : [];\n            if (set.includes(me)) {\n                isApprover = true;\n                if (!approved.has(t.goal_id))\n                    canApproveNow = true;\n            }\n            return {\n                goal: seen ? { id: g.id, title: g.title } : null,\n                from_share: seen ? t.from_share : null,\n                /** The goal's target now (differs from from_share when the proposal launched, or the goal moved). */\n                current_share: seen ? (g.target_share ?? null) : null,\n                target_share: seen ? t.target_share : null,\n                base_version: seen ? t.base_version : null,\n                approvers: seen ? set.map((u) => person(u)) : [],\n                approved_by: seen ? person(approved.get(t.goal_id) ?? null) : null,\n            